INSERT INTO `pages` (`id`, `name`, `slug`, `en_content`, `nl_content`, `en_meta_title`, `nl_meta_title`, `en_meta_description`, `nl_meta_description`, `en_meta_keywords`, `nl_meta_keywords`, `status`, `sort_order`, `is_homepage`, `show_in_menu`, `published_at`, `created_at`, `updated_at`) VALUES
(1, 'About', 'about', '<p><strong>Welcome to TravelBookingPanel</strong></p><p>TravelBookingPanel is a modern <strong>travel booking demo platform</strong> designed to showcase how a professional travel agency website can look and function.</p><p>Our platform demonstrates booking flows for:</p><p>✈️ Flights</p><p>🏨 Hotels</p><p>🛂 Visa services</p><p>🧳 Tour packages</p><p>🕋 Umrah services</p><p>This website is created <strong>for presentation and demonstration purposes only</strong>. It allows travel agencies to visualize the layout, features, and user experience of a complete travel booking system.</p><p><strong>Important Disclaimer:</strong><br>TravelBookingPanel is a <strong>demo website</strong>. All bookings, prices, availability, and services shown on this platform are <strong>not real</strong>. No actual reservations, confirmations, or transactions are processed through this website.</p><p>Our goal is to help travel agencies understand how their future website can look, feel, and operate before launching a live system.</p>', '<h2>Onze missie</h2><p>Door samen te werken met internationale touroperators en luchtvaartmaatschappijen die groot inkopen, kunnen wij kortingen aanbieden die u elders zelden ziet.</p><p>Wij geloven in transparantie, gemak en persoonlijke service.<br>Al onze boekingen worden veilig online verwerkt — snel, duidelijk en betaalbaar.</p><p><strong>Onze missie is om betaalbaar reizen mogelijk te maken voor iedereen, zonder concessies te doen aan kwaliteit of service.</strong></p><h2>Ons kantoor in Amsterdam</h2><p>Ons kantoor is gevestigd aan de <strong>Keizersgracht 520 in Amsterdam</strong> en kan <strong>op afspraak</strong> worden bezocht.</p><p>Omdat wij alles digitaal regelen, kunt u eenvoudig vanuit huis boeken zonder gedoe.</p><h2>Praktisch</h2><p>Wij werken voornamelijk online om de kosten laag te houden en deze besparingen direct door te geven aan onze klanten.<br>Dat betekent <strong>betere prijzen voor u</strong> 😊</p>', 'About Us | TravelBookingPanel', 'Over Ons | Travel Panel', 'Learn more about our travel services, mission, and commitment to affordable and secure bookings.', 'Lees meer over onze reisdiensten, missie en toewijding aan betaalbare en veilige boekingen.', 'about us, travel services, affordable travel, flight deals', 'over ons, reisdiensten, betaalbaar reizen, vliegtickets', 'published', 1, 0, 1, '2025-12-25 20:28:34', '2025-12-25 20:28:34', '2026-01-30 11:55:41'),
(2, 'Privacy Policy', 'privacy-policy', '<h2><strong>Privacy Policy</strong></h2><p><strong>TravelBookingPanel Privacy Policy</strong></p><p>Your privacy is important to us.</p><h3>1. Demo Purpose Only</h3><p>TravelBookingPanel is a demo platform. Any information entered on this website is used <strong>only for testing and demonstration</strong> purposes.</p><h3>2. Data Collection</h3><p>No real bookings or transactions are processed</p><p>No payment information is collected</p><p>Users are advised <strong>not to enter real personal or financial data</strong></p><h3>3. Third-Party Integration</h3><p>This website is <strong>not connected</strong> to any airline, hotel, visa office, tour operator, or Umrah service provider. All data displayed is sample data.</p><h3>4. Data Security</h3><p>Basic security practices are followed; however, since this is a demo system, data should not be considered permanent or production-level.</p>', NULL, 'TravelBookingPanel Privacy Policy', NULL, 'TravelBookingPanel is a demo platform. Any information entered on this website is used only for testing and demonstration purposes.', NULL, 'flight booking, cheap flights, airline tickets, travel', NULL, 'published', 92, 1, 1, '2026-01-22 01:42:06', '2026-01-22 01:42:06', '2026-01-30 11:57:02'),
(3, 'Terms & Conditions', 'terms-conditions', '<h2><strong>Terms &amp; Conditions</strong></h2><p><strong>Terms and Conditions – TravelBookingPanel</strong></p><p>By using this website, you agree to the following terms:</p><h3>1. Demo Website</h3><p>TravelBookingPanel is a <strong>non-commercial demo platform</strong> created solely for presentation and showcasing purposes.</p><h3>2. No Real Bookings</h3><p>No actual flight, hotel, visa, tour, or Umrah bookings are made</p><p>No confirmations, tickets, or vouchers are issued</p><h3>3. Sample Content</h3><p>All prices, schedules, availability, and descriptions displayed on this website are <strong>example data only</strong> and do not reflect real market information.</p><h3>4. Limitation of Liability</h3><p>TravelBookingPanel is not responsible for any loss, misunderstanding, or misuse resulting from the use of this demo website.</p><h3>5. Intellectual Property</h3><p>All designs, layouts, and content displayed on this website are for demonstration purposes and may not be copied or used commercially without permission.</p>', NULL, 'Terms and Conditions – TravelBookingPanel', NULL, 'TravelBookingPanel is a non-commercial demo platform created solely for presentation and showcasing purposes.', NULL, 'flight booking, cheap flights, airline tickets, travel', NULL, 'published', 93, 0, 1, '2026-01-30 02:26:45', '2026-01-30 02:26:45', '2026-01-30 11:57:48');
